import Foundation
import Testing
@testable import MediaCore

// The correction's formula (docs/superpowers/specs/2026-10-18-straighten-the-picture-design.md) is written once in Swift and once in
// JavaScript for the browser; Fixtures/picture-correction-vectors.json (generated by Tools/picture-correction-vectors.py, which holds
// the spec's formula written independently of both) pins every renderer to the same result. Read via #filePath (the target excludes
// Fixtures from its sources).

private struct Vector: Decodable, Sendable, CustomStringConvertible {
    var straighten: Double
    var level: Double
    var across: Double
    var down: Double
    var source: Double

    var description: String { "straighten \(straighten) level \(level) across \(across) down \(down) -> \(source)" }
}

private func vectors() throws -> [Vector] {
    struct File: Decodable { var vectors: [Vector] }
    let url = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appending(path: "Fixtures/picture-correction-vectors.json")
    return try JSONDecoder().decode(File.self, from: Data(contentsOf: url)).vectors
}

private func decode(_ json: String) throws -> PictureCorrection {
    try JSONDecoder().decode(PictureCorrection.self, from: Data(json.utf8))
}

/// A 16-bit PGM as `remapMaps` writes it: "P5\n<w> <h>\n65535\n", then big-endian samples, row by row.
private struct PGM {
    let width: Int
    let height: Int
    let header: String
    private let samples: [UInt8]

    init(_ data: Data) throws {
        let bytes = [UInt8](data)
        var lines: [String] = []
        var index = 0
        while lines.count < 3, index < bytes.count {
            guard let end = bytes[index...].firstIndex(of: 0x0A) else { break }
            lines.append(String(decoding: bytes[index..<end], as: UTF8.self))
            index = end + 1
        }
        let size = lines.count == 3 ? lines[1].split(separator: " ").compactMap { Int($0) } : []
        guard lines.count == 3, lines[0] == "P5", lines[2] == "65535", size.count == 2 else { throw CocoaError(.fileReadCorruptFile) }
        width = size[0]
        height = size[1]
        header = String(decoding: bytes[..<index], as: UTF8.self)
        samples = Array(bytes[index...])
        guard samples.count == width * height * 2 else { throw CocoaError(.fileReadCorruptFile) }
    }

    /// The sample in column `x`, row `y`.
    func callAsFunction(_ x: Int, _ y: Int) -> Int {
        let offset = (y * width + x) * 2
        return Int(samples[offset]) << 8 | Int(samples[offset + 1])
    }
}

@Suite struct PictureCorrectionTests {
    @Test func everyVectorMatches() throws {
        let all = try vectors()
        #expect(all.count == 676)
        for v in all {
            let c = PictureCorrection(straighten: v.straighten, level: v.level)
            #expect(abs(c.sourceFraction(across: v.across, down: v.down) - v.source) < 1e-9, "\(v)")
        }
    }

    @Test func offIsTheIdentity() {
        for d in stride(from: 0.0, through: 1, by: 0.05) {
            #expect(PictureCorrection.off.sourceFraction(across: 0.3, down: d) == d)
        }
    }

    @Test func topAndBottomStayAndEveryColumnIsIncreasing() {
        let settings = [(0.60, 0.40), (0.60, -0.40), (-0.60, 0.40), (-0.60, -0.40), (0.40, 0.15)]
        for (straighten, level) in settings {
            let c = PictureCorrection(straighten: straighten, level: level)
            for column in 0...100 {
                let across = Double(column) / 100
                #expect(c.sourceFraction(across: across, down: 0) == 0, "\(c) across \(across)")
                #expect(c.sourceFraction(across: across, down: 1) == 1, "\(c) across \(across)")
                var previous = -1.0
                for row in 0...100 {
                    let fs = c.sourceFraction(across: across, down: Double(row) / 100)
                    #expect(fs >= 0 && fs <= 1, "\(c) across \(across) row \(row): \(fs)")
                    #expect(fs > previous, "\(c) across \(across) row \(row): \(fs) after \(previous)")
                    previous = fs
                }
            }
        }
    }

    @Test func valuesAreClampedAndRounded() {
        #expect(PictureCorrection(straighten: 2, level: -1) == PictureCorrection(straighten: 0.60, level: -0.40))
        #expect(PictureCorrection(straighten: 0.404, level: 0.151).straighten == 0.40)
        #expect(PictureCorrection(straighten: 0.404, level: 0.151).level == 0.15)
        #expect(PictureCorrection(straighten: .nan, level: .infinity) == .off)
        #expect(PictureCorrection(straighten: 0, level: 0).isOff && !PictureCorrection(straighten: 0.01).isOff)
        #expect(!PictureCorrection(level: -0.01).isOff)
        // A value that rounds to nothing is off.
        #expect(PictureCorrection(straighten: 0.004, level: -0.004).isOff)
    }

    @Test func decodingNeverFails() throws {
        #expect(try decode("{}") == .off)
        #expect(try decode(#"{"straighten": 0.4}"#) == PictureCorrection(straighten: 0.40, level: 0))
        #expect(try decode(#"{"straighten": "x", "level": 0.15}"#) == PictureCorrection(straighten: 0, level: 0.15))
        #expect(try decode(#"{"straighten": 9}"#) == PictureCorrection(straighten: 0.60, level: 0))
        #expect(try decode(#"{"straighten": null, "level": -9}"#) == PictureCorrection(straighten: 0, level: -0.40))
        // Not an object at all: still readable.
        #expect(try decode("[1, 2]") == .off)
        #expect(try decode("7") == .off)
    }

    @Test func encodingRoundTrips() throws {
        let c = PictureCorrection(straighten: -0.35, level: 0.12)
        let data = try JSONEncoder().encode(c)
        #expect(try JSONDecoder().decode(PictureCorrection.self, from: data) == c)
    }

    @Test func backyardStretchesAboutTwoPointSevenTimes() {
        let backyard = PictureCorrection(straighten: 0.40, level: 0.15)
        #expect(abs(backyard.landing - (0.5 + 2.0 / 3.0 * 0.40)) < 1e-12)
        #expect(abs(backyard.landing - 0.766667) < 1e-6)
        #expect(abs(backyard.horizon(across: 0) - 0.35) < 1e-12)
        #expect(abs(backyard.horizon(across: 1) - 0.65) < 1e-12)
        #expect(abs(backyard.largestStretch - 2.714958691380824) < 1e-9)
        #expect(abs(PictureCorrection(straighten: 0.10, level: 0).largestStretch - 1.1315687104968346) < 1e-9)
        #expect(PictureCorrection.off.largestStretch == 1)
    }

    @Test func theStaticProviderIsNilWhenOff() {
        #expect(StaticPictureCorrection(.off).current == nil)
        #expect(StaticPictureCorrection(nil).current == nil)
        let c = PictureCorrection(straighten: 0.2)
        #expect(StaticPictureCorrection(c).current == c)
    }

    // MARK: The ffmpeg maps (PictureCorrection+Remap.swift)

    @Test func theMapsAreTwiceAsTallAndFollowTheFormula() throws {
        let c = PictureCorrection(straighten: 0.4, level: 0.15)
        #expect(PictureCorrection.remapSupersample == 2)
        let maps = c.remapMaps(width: 64, height: 32)
        let x = try PGM(maps.x), y = try PGM(maps.y)
        #expect(x.header == "P5\n64 64\n65535\n" && y.header == "P5\n64 64\n65535\n")
        #expect(maps.x.count == 15 + 64 * 64 * 2 && maps.y.count == maps.x.count)
        // The x map is the column itself (the warp is vertical only).
        for row in 0..<64 { for column in 0..<64 { #expect(x(column, row) == column, "x(\(column), \(row))") } }
        #expect(x(10, 17) == 10)
        // The top and bottom rows stay where the edge is not squeezed (the middle column).
        #expect(y(32, 0) == 0)
        #expect(y(32, 63) == 63)
        #expect(y(0, 0) == 0)
        // At the left edge the rows below the line are squeezed 2.7×: the last row's centre falls in the camera's row 62.
        #expect(y(0, 63) == 62)
        // Every sampled pixel is the formula at the pixel's centre, rounded down to the row it falls in.
        for sample in 0..<20 {
            let column = (sample * 37 + 3) % 64, row = (sample * 23 + 5) % 64
            let fs = c.sourceFraction(across: (Double(column) + 0.5) / 64, down: (Double(row) + 0.5) / 64)
            let expected = min(63, max(0, Int((fs * 64).rounded(.down))))
            #expect(y(column, row) == expected, "y(\(column), \(row))")
        }
        // Every column increases (no folding) and stays inside the picture.
        for column in 0..<64 {
            let rows = (0..<64).map { y(column, $0) }
            #expect(zip(rows, rows.dropFirst()).allSatisfy { $0 <= $1 } && rows.allSatisfy { (0..<64).contains($0) }, "column \(column)")
        }
    }

    @Test func theChromaMapsAreHalfAsWideAndFollowTheFormulaAtTheirOwnSize() throws {
        // The supersampled 4:2:0 picture is 64 × 64 (luma), so its chroma planes are 32 × 32: the picture's own height.
        let c = PictureCorrection(straighten: 0.4, level: 0.15)
        let maps = c.remapMaps(width: 64, height: 32)
        let x = try PGM(maps.chromaX), y = try PGM(maps.chromaY)
        #expect(x.header == "P5\n32 32\n65535\n" && y.header == "P5\n32 32\n65535\n")
        #expect(maps.chromaX.count == 15 + 32 * 32 * 2 && maps.chromaY.count == maps.chromaX.count)
        for row in 0..<32 { for column in 0..<32 { #expect(x(column, row) == column, "chroma x(\(column), \(row))") } }
        for sample in 0..<20 {
            let column = (sample * 13 + 1) % 32, row = (sample * 7 + 2) % 32
            let fs = c.sourceFraction(across: (Double(column) + 0.5) / 32, down: (Double(row) + 0.5) / 32)
            let expected = min(31, max(0, Int((fs * 32).rounded(.down))))
            #expect(y(column, row) == expected, "chroma y(\(column), \(row))")
        }
        #expect(y(16, 0) == 0 && y(16, 31) == 31)
        for column in 0..<32 {
            let rows = (0..<32).map { y(column, $0) }
            #expect(zip(rows, rows.dropFirst()).allSatisfy { $0 <= $1 } && rows.allSatisfy { (0..<32).contains($0) }, "chroma column \(column)")
        }
        // The luma maps are the same as ever.
        #expect(try PGM(maps.x).header == "P5\n64 64\n65535\n" && maps.y == c.remapMaps(width: 64, height: 32).y)
    }

    @Test func offMapsAreTheIdentity() throws {
        let maps = PictureCorrection.off.remapMaps(width: 16, height: 8)
        let x = try PGM(maps.x), y = try PGM(maps.y)
        #expect(x.width == 16 && x.height == 16 && y.width == 16 && y.height == 16)
        for row in 0..<16 {
            for column in 0..<16 {
                #expect(x(column, row) == column && y(column, row) == row, "(\(column), \(row))")
            }
        }
        let chromaX = try PGM(maps.chromaX), chromaY = try PGM(maps.chromaY)
        #expect(chromaX.width == 8 && chromaX.height == 8 && chromaY.width == 8 && chromaY.height == 8)
        for row in 0..<8 {
            for column in 0..<8 {
                #expect(chromaX(column, row) == column && chromaY(column, row) == row, "chroma (\(column), \(row))")
            }
        }
    }

    @Test func theRemapChainIsExact() {
        #expect(PictureCorrection.ffmpegRemapChain(input: "0:v:0", width: 1920, height: 852, xMap: "1:v", yMap: "2:v", chromaXMap: "3:v", chromaYMap: "4:v", output: "cbw")
            == "[0:v:0]scale=1920:1704:flags=bicubic,format=yuv420p,extractplanes=y+u+v[cbpy][cbpu][cbpv];[1:v]format=gray16[cbx];[2:v]format=gray16[cby];[3:v]format=gray16,split[cbcx1][cbcx2];[4:v]format=gray16,split[cbcy1][cbcy2];[cbpy][cbx][cby]remap=format=gray[cbry];[cbpu][cbcx1][cbcy1]remap=format=gray[cbru];[cbpv][cbcx2][cbcy2]remap=format=gray[cbrv];[cbry][cbru][cbrv]mergeplanes=map0s=0:map0p=0:map1s=1:map1p=0:map2s=2:map2p=0:format=yuv420p,scale=1920:852:flags=area[cbw]")
    }
}
